<script setup lang="ts">
const route = useRoute();

const tableToken = computed(() => {
  const value = route.params.token;
  return Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
});

const { itemCount, addItem } = useCart(tableToken.value);
const { data, status, error, refresh } = await useTableMenu(tableToken);

useHead({
  title: "Меню — SeatMe",
});
</script>

<template>
  <LayoutContainer class="pb-28 pt-6">
    <div class="mx-auto w-full max-w-md">
      <MenuListSkeleton v-if="status === 'pending'" />

      <UiErrorState
        v-else-if="error"
        message="Не удалось загрузить меню"
        @retry="refresh"
      />

      <template v-else-if="data">
        <MenuHeader :table-name="data.table.name" />

        <MenuList :items="data.items" @add="addItem" />
      </template>
    </div>
  </LayoutContainer>

  <CartBar :item-count="itemCount" />
</template>
