export function useCart(tableToken: string) {
  const quantities = useState<Record<string, number>>(
    `cart:${tableToken}`,
    () => ({}),
  );

  const itemCount = computed(() =>
    Object.values(quantities.value).reduce(
      (total, quantity) => total + quantity,
      0,
    ),
  );

  function addItem(itemId: string): void {
    quantities.value[itemId] = (quantities.value[itemId] ?? 0) + 1;
  }

  return {
    quantities: readonly(quantities),
    itemCount,
    addItem,
  };
}
